"""Design-only logical frame contract. Not a native wire encoder or runtime consumer."""
FRAME_TYPES=['enrollment','identity_proof','generation_proof','heartbeat','progress','completed_work_witness','approval_state','enforcement_state','quarantine','drain','recovery_observation']
FIELDS=['frame_identity','frame_type','frame_version','participant_identity','participant_generation','deployment_id','incarnation_id','boot_epoch','sequence','emitted_boottime_us','observation_epoch','registry_revision','payload_digest','challenge','witness_type','witness_generation','witness_sequence','independent_verifier_identity','verification_result']
COMPLETION=['operation_class','operation_id','target_anchor_identity','input_revision','completed_sequence','result_digest','durable_result_reference','independent_observation_reference']
PAYLOADS={'enrollment':['binding_id','slot','role_oid','db_oid','role_name','db_name','postmaster_start','backend_start','context_fingerprint','policy_hash'],'identity_proof':['boot_start','target_start','namespace_digest','pidfd_anchor_digest'],'generation_proof':['slot','generation','ledger_revision','allocation_id'],'heartbeat':['health_class'],'progress':COMPLETION,'completed_work_witness':COMPLETION,'approval_state':COMPLETION+['approval_generation','approval_hash'],'enforcement_state':COMPLETION+['target_outcome'],'quarantine':['ledger_revision','generation','reason','current_registration_digest'],'drain':['target_set_digest','ownership_digest','drain_state','release_authorized'],'recovery_observation':['census_observation_epoch','registry_revision','postmaster_generation','receiver_generation','supervisor_generation','anchor_digest','enrollment_generation','new_eligibility']}
PATHS={
 'enrollment':('ENROLLMENT_ENTRYPOINT','RECEIVER','HEALTH_GUARD','OS atomic anchor + independent live catalog/allocation registry'),
 'identity_proof':('TRUSTED_BOOTSTRAP','RECEIVER','HEALTH_GUARD','Independent retained OS anchor/start/namespace plus server-derived identity'),
 'generation_proof':('TRUSTED_GENERATION_LEDGER','RECEIVER','HEALTH_GUARD','Independent current slot ledger revision; no participant-selected generation'),
 'heartbeat':('ANCHORED_PARTICIPANT','DEPENDENCY_CONSUMER','HEALTH_GUARD','Original emission time and OS anchor; grants liveness only, never completed work'),
 'progress':('ANCHORED_PARTICIPANT','DEPENDENCY_CONSUMER','HEALTH_GUARD','Independently confirmed completed operation, not a loop counter'),
 'completed_work_witness':('ANCHORED_PARTICIPANT','DEPENDENCY_CONSUMER','HEALTH_GUARD','External target/catalog/publication result, exact operation/challenge/generation/sequence'),
 'approval_state':('APPROVAL_PRODUCER','APPROVAL_CONSUMER','HEALTH_GUARD','Original test-only signature, exact publication generation and independent consumed result'),
 'enforcement_state':('ENFORCEMENT_WORKER','SUPERVISOR','HEALTH_GUARD','Anchored target exit/query cancellation outcome; signal ACK alone insufficient'),
 'quarantine':('HEALTH_GUARD','SUPERVISOR_AND_RECEIVER','HOST_PLATFORM','Independent guard anchor and current external quarantine/tombstone ledger'),
 'drain':('SUPERVISOR','ENFORCEMENT_WORKER','HEALTH_GUARD','Independent owned target set, retained ownership and actual target outcomes'),
 'recovery_observation':('CENSUS_OBSERVER','SUPERVISOR_AND_RECEIVER','HEALTH_GUARD','Independent current census epoch + enrollment/promotion registry CAS; cannot restore eligibility')}
def contract():
    frames=[]
    for name in FRAME_TYPES:
        producer,consumer,verifier,proof=PATHS[name]
        frames.append({'FRAME_TYPE':name,'FRAME_VERSION':'DESIGN_LOGICAL_V2_NOT_NATIVE_WIRE','PRODUCER':producer,'CONSUMER':consumer,'INDEPENDENT_VERIFIER':verifier,'IDENTITY_BINDING':'Exact externally current boot/start/namespace/pidfd slot identity; participant_identity is opaque anchored record ID, never bare PID','GENERATION_BINDING':'Exact independently current participant generation and registry revision; old/future values deny','DEPLOYMENT_BINDING':'Exact independently bound disposable deployment UUID','INCARNATION_BINDING':'Exact current disposable incarnation UUID','SEQUENCE_BINDING':'Per participant/generation/channel, strictly next sequence; no global mixed counter; gaps/out-of-order require resynchronization without eligibility','TIMESTAMP_SEMANTICS':'Original CLOCK_BOOTTIME microseconds in exact boot epoch; 0<=emission<=decision_now; never stamp at dequeue; revalidate freshness immediately before decision','PAYLOAD_DIGEST':'SHA256 of canonical UTF-8 JSON payload (sorted keys, compact, UTF-8, no NaN/duplicates); digest detects substitution, does not establish authenticity','ANTI_REPLAY_FIELD':'Independent verifier-issued one-use challenge + generation/channel sequence and observation/registry revision; persisted consumption in external observer ledger','FAILURE_ACTION':'Deny ACCEPT/promotion; monotonic quarantine and ownership retention/reconciliation. Stale observations never mutate newer registration or create eligibility.','REQUIRED_FIELDS':FIELDS,'PAYLOAD_REQUIRED_FIELDS':PAYLOADS[name],'PAYLOAD_UNKNOWN_FIELDS_ALLOWED':False,'CORROBORATION_REQUIRED':proof,'verification_result_semantics':'UNKNOWN until independent verifier has actually checked its own observations; producer-provided VERIFIED string has no authority','implementation_status':'DESIGN_ONLY_NO_NEW_NATIVE_WIRE'})
    return {'frames':frames,'required_fields':FIELDS,'logical_serialization':'Canonical UTF-8 sorted-key JSON; exact closed field set and strict types; not serialized on any native socket in this gate','selected_witness':'GENERATION_BOUND_COMPLETION_RECEIPT_WITH_EXTERNAL_CORROBORATION','receipt_payload_fields':['operation_class','operation_id','target_anchor_identity','input_revision','completed_sequence','result_digest','durable_result_reference','independent_observation_reference'],'completion_rule':'Receipt emitted after successful work; verified independently against actual target outcome; durable database action references its committed transaction/receipt; OS/census action references independently observed target or applicable snapshot. Send ACK and fresh heartbeat never suffice.','heartbeat_rule':'Never advances completed-operation sequence or grants participant progress','canonical_scope':'TEST_ONLY_NONAUTHORITATIVE; no production or numeric authority'}
